'use strict';
const { test } = require('node:test');
const assert = require('node:assert');
const { filterNames } = require('../src/lib.js');

const TEAM = [
  'Alice Johnson',
  'Boris Petrov',
  'Carol Nguyen',
  'David Okafor',
  'Elena Sokolova',
  'Frank Miller',
];

test('empty query returns every name', () => {
  assert.deepStrictEqual(filterNames(TEAM, ''), TEAM);
});

test('whitespace-only query returns every name', () => {
  assert.deepStrictEqual(filterNames(TEAM, '   '), TEAM);
});

test('missing query returns every name', () => {
  assert.deepStrictEqual(filterNames(TEAM, undefined), TEAM);
  assert.deepStrictEqual(filterNames(TEAM, null), TEAM);
});

test('matches are case-insensitive', () => {
  assert.deepStrictEqual(filterNames(TEAM, 'alice'), ['Alice Johnson']);
  assert.deepStrictEqual(filterNames(TEAM, 'ALICE'), ['Alice Johnson']);
  assert.deepStrictEqual(filterNames(TEAM, 'AlIcE'), ['Alice Johnson']);
});

test('matches a substring anywhere in the name, not just the start', () => {
  assert.deepStrictEqual(filterNames(TEAM, 'ok'), ['David Okafor']);
  assert.deepStrictEqual(filterNames(TEAM, 'sokolova'), ['Elena Sokolova']);
});

test('a query can match several names', () => {
  assert.deepStrictEqual(filterNames(TEAM, 'o'), [
    'Alice Johnson',
    'Boris Petrov',
    'Carol Nguyen',
    'David Okafor',
    'Elena Sokolova',
  ]);
});

test('matches across the space in a full name', () => {
  assert.deepStrictEqual(filterNames(TEAM, 'ris pet'), ['Boris Petrov']);
});

test('no match returns an empty array', () => {
  assert.deepStrictEqual(filterNames(TEAM, 'zzz'), []);
});

test('surrounding whitespace in the query is ignored', () => {
  assert.deepStrictEqual(filterNames(TEAM, '  carol  '), ['Carol Nguyen']);
});

test('query is treated as literal text, not a regular expression', () => {
  assert.deepStrictEqual(filterNames(TEAM, '.*'), []);
  assert.deepStrictEqual(filterNames(['a.b', 'axb'], '.'), ['a.b']);
});

test('original order is preserved', () => {
  assert.deepStrictEqual(filterNames(['Zoe', 'Adam', 'Zach'], 'z'), ['Zoe', 'Zach']);
});

test('the source array is not mutated', () => {
  const source = TEAM.slice();
  filterNames(source, 'alice');
  assert.deepStrictEqual(source, TEAM);
});

test('filtering an empty list yields an empty list', () => {
  assert.deepStrictEqual(filterNames([], 'alice'), []);
});

test('filter output feeds renderList', () => {
  const { renderList } = require('../src/lib.js');
  const html = renderList(filterNames(TEAM, 'a'));
  assert.match(html, /Alice Johnson/);
  assert.doesNotMatch(html, /Boris Petrov/);
});

