// Pure filter helper: keeps names containing the query, case-insensitively.
// The query is matched as literal text (no regex), order is preserved and the
// source array is never mutated. Blank/absent query means "no filtering".
function filterNames(names, query) {
  const needle = String(query == null ? '' : query).trim().toLowerCase();
  if (needle === '') return names.slice();
  return names.filter((name) => String(name).toLowerCase().includes(needle));
}

// Dual environment: browser (script tag, no module) + node tests (require).
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { renderList, filterNames };
}

